def verify_oia025() -> None:
    if not OIA025.exists():
        raise RuntimeError(f"Actual OIA-025 production module missing: {OIA025}")
    source = OIA025.read_text(encoding="utf-8")
    required = [
        'SCHEMA_VERSION = "OIA-025"',
        'ENGINE_ID = "OIA-025"',
        'CERTIFICATION_POLICY_ID',
        'SESSION_CERTIFIED',
        'ENTRY_CERTIFIED',
        'source_readiness_hash',
        'source_session_hash',
        'source_activation_hash',
        'source_claim_hash',
        'source_manifest_hash',
        'source_batch_hash',
        'source_readiness_entry_hash',
        'certification_entry_hash',
        'certification_hash',
        'read_only_corpus',
        'research_execution_allowed',
        'qseries_handoff_allowed',
        'market_order_creation_allowed',
        'funds_movement_allowed',
        'portfolio_mutation_allowed',
    ]
    missing = [token for token in required if token not in source]
    if missing:
        raise RuntimeError(f"Actual OIA-025 production contract mismatch: {missing}")


def write_full_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source.rstrip() + "\n", encoding="utf-8")
    print(f"[OK] FULL REPLACEMENT: {path}")


def update_init() -> None:
    source = INIT.read_text(encoding="utf-8") if INIT.exists() else "__all__ = []\n"
    marker = "from .oracle_certified_research_evidence_collection_manifest_builder import ("
    if marker not in source:
        source = source.rstrip() + "\n" + INIT_BLOCK
        INIT.write_text(source.rstrip() + "\n", encoding="utf-8")
        print(f"[OK] PACKAGE UPDATED: {INIT}")
    else:
        print(f"[OK] PACKAGE ALREADY CURRENT: {INIT}")


def main() -> int:
    print("=" * 40)
    print(" OIA-026 INSTALLER")
    print(" CERTIFIED RESEARCH EVIDENCE COLLECTION")
    print(" READ-ONLY MANIFEST BUILDER")
    print("=" * 40)
    verify_oia025()
    print("[OK] Actual OIA-025 certification contract verified")
    write_full_replacement(PRODUCTION, PRODUCTION_SOURCE)
    write_full_replacement(TEST, TEST_SOURCE)
    update_init()
    py_compile.compile(str(PRODUCTION), doraise=True)
    py_compile.compile(str(TEST), doraise=True)
    py_compile.compile(str(INIT), doraise=True)
    print("[OK] Production, test, and package syntax verified")
    result = subprocess.run([sys.executable, str(TEST)], cwd=str(ROOT), check=False)
    if result.returncode != 0:
        raise SystemExit(result.returncode)
    print("[OK] OIA-026 test executed automatically")
    print()
    print("[DONE] OIA-026 certified research evidence collection manifest builder installed")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
